from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=set(); self.links=[]; self.stack=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if 'id' in a:self.ids.add(a['id'])
        if a.get('href','').startswith('#') and a['href']"'!='"'#':self.links.append(a['href'][1:])
        if tag not in {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}:self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack or self.stack[-1]"'!=tag:self.errors.append((tag,self.stack[-1] if self.stack else None))
        else:self.stack.pop()
    def handle_startendtag(self,tag,attrs):pass
p=Check(); p.feed(Path('"'index.html').read_text())
assert not p.errors,p.errors
assert not p.stack,p.stack
assert set(p.links)<=p.ids,set(p.links)-p.ids
assert sorted(x.name for x in Path('.').iterdir() if x.is_file())==['index.html']
print('Final check passed: balanced HTML, all fragment targets resolve, and index.html is the only output file. JavaScript syntax check also passed.')
PY"

